#include "../models/film_shell/FilmShell.cpp"
#include <sofa/component/statecontainer/MechanicalObject.h>
#include <iostream>
template<class Parent>struct FilmAccumulator:Parent{double a[81][81]{};void add(sofa::SignedIndex r,sofa::SignedIndex c,double v)override{a[r][c]+=v;}void add(sofa::SignedIndex r,sofa::SignedIndex c,float v)override{add(r,c,double(v));}};
int main(){try{for(unsigned regime:{0u,1u,2u,3u}){using T=regrip_film::FilmShell;auto state=sofa::core::objectmodel::New<sofa::component::statecontainer::MechanicalObject<T::Types>>();state->resize(9);auto field=sofa::core::objectmodel::New<T>(state.get());field->nx.setValue(3);field->ny.setValue(3);if(regime==1){field->plane.setValue(-.01);field->contactStiffness.setValue(.00001);}if(regime==2)field->slopeFixture.setValue(100);auto rest=field->model().rest();T::VecCoord x(9);for(int i=0;i<9;++i)for(int j=0;j<3;++j)x[i][j]=rest[i][j];if(regime==3){field->displacementDofs.setValue(true);for(auto&p:x)p={0,0,0};}x[7][2]=.02;state->write(sofa::core::vec_id::write_access::position)->setValue(x);
 T::DataVecCoord pos;pos.setValue(x);T::DataVecDeriv force,velocity,dx,df;T::VecDeriv delta(9);for(int i=0;i<9;++i)delta[i]={.001*i,-.002*i,.003*i};dx.setValue(delta);velocity.setValue(T::VecDeriv(9));force.setValue(T::VecDeriv(9));sofa::core::MechanicalParams mp;field->addForce(&mp,force,pos,velocity);
 FilmAccumulator<sofa::core::behavior::StiffnessMatrixAccumulator>acc;sofa::core::behavior::StiffnessMatrix matrix;matrix.setMatrixAccumulator(&acc,state.get());field->buildStiffnessMatrix(&matrix);
 for(double factor:{0.,2.5,-.25}){mp.setKFactor(factor);df.setValue(T::VecDeriv(9));field->addDForce(&mp,df,dx);for(int i=0;i<27;++i){double expected=0;for(int j=0;j<27;++j)expected+=factor*acc.a[i][j]*delta[j/3][j%3];if(std::abs(df.getValue()[i/3][i%3]-expected)>1e-11)throw std::runtime_error("film dforce/matrix");}}
 for(double h:{2e-5,1e-5,5e-6}){auto p=x,m=x;p[7][2]+=h;m[7][2]-=h;T::DataVecCoord xp,xm;xp.setValue(p);xm.setValue(m);T::DataVecDeriv fp,fm;fp.setValue(T::VecDeriv(9));fm.setValue(T::VecDeriv(9));field->addForce(&mp,fp,xp,velocity);field->addForce(&mp,fm,xm,velocity);double error=0;for(int i=0;i<27;++i)error=std::max(error,std::abs((fp.getValue()[i/3][i%3]-fm.getValue()[i/3][i%3])/(2*h)-acc.a[i][23]));std::cout<<"actual film API Force/dForce/matrix h="<<h<<" FD="<<error<<'\n';if(error>1e-8)throw std::runtime_error("film API FD");}std::cout<<"PASS regime="<<regime<<'\n';}return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
